function TerminalChatResponseItem({
  item,
  group,
  fullStdout = false,
  toolCallMap = new Map(),
  loading = false,
  theme,
}: {
  item?: ChatCompletionMessageParam;
  group?: GroupedResponseItem;
  fullStdout?: boolean;
  toolCallMap?: Map<string, any>;
  loading?: boolean;
  theme: Theme;
}): React.ReactElement {
  if (group) {
    return (
      <TerminalChatResponseToolBatch
        group={group}
        fullStdout={fullStdout}
        toolCallMap={toolCallMap}
        theme={theme}
      />
    );
  }

  if (!item) return <></>;

  switch (item.role) {
    case "user":
      return <TerminalChatResponseMessage message={item} theme={theme} />;
    case "assistant":
      return (
        <>
          <TerminalChatResponseMessage message={item} theme={theme} />
          {item.tool_calls?.map((toolCall, i) => {
            return (
              <TerminalChatResponseToolCall
                key={i}

esponseMessage message={item} theme={theme} />
          {item.tool_calls?.map((toolCall, i) => {
            return (
              <TerminalChatResponseToolCall
                key={i}
                message={toolCall}
                loading={loading}
                theme={theme}
              />
            );
          })}
        </>
      );
    case "tool":
      return (
        <TerminalChatResponseMessage
          message={item}
          fullStdout={fullStdout}
          toolCallMap={toolCallMap}
          theme={theme}
        />
      );
    default:
      break;
  }
  // Fallback for any other message type
  return <TerminalChatResponseGenericMessage message={item} />;
}

